import 'package:cloud_firestore/cloud_firestore.dart'; import '../../core/models/agent_listing.dart';
class AurenAgentMarketplaceRepository{final FirebaseFirestore _db; AurenAgentMarketplaceRepository({FirebaseFirestore? db}):_db=db??FirebaseFirestore.instance; Stream<List<AurenAgentListing>> watchPublished()=>_db.collection('agent_listings').where('state',isEqualTo:'published').orderBy('name').limit(100).snapshots().map((s)=>s.docs.map((d)=>AurenAgentListing.fromMap(d.data())).toList());}
